def addWorkDays(timestamp, days):
    """adds working days (mon-fri) to a unix timestamp"""
    t = timestamp
    added = 0
    while added < days:
        t = t + SECONDS_PER_DAY
        wd = time.localtime(t).tm_wday
        if wd < 5:
            added = added + 1
    return t

